#include <bits/stdc++.h>
using namespace std;
#define ll long long
const int MOD_A = 998244353;
const int MOD_B = 1000000007;
const int BASE = 1000000;
vector<int> sequences[7];
int partialSum[7];
ll totalN;
ll totalCount, totalAnswer;

void generateSequences(int level, int prefix) {
    ++totalCount;
    sequences[level].push_back((totalCount - prefix + MOD_A) % MOD_A);
    partialSum[level] = (partialSum[level] + (totalCount - prefix + MOD_A) % MOD_A) % MOD_B;
    if (level == 6) return;
    for (int digit = 0; digit < 10; ++digit)
        generateSequences(level + 1, prefix * 10 + digit);
}

void processNumber(ll x) {
    if (x > totalN) return;
    if (x * BASE + BASE - 1 <= totalN && x * BASE * 10 > totalN) {
        ll currentCount = totalCount;
        for (int i = 0, factor = 1; i <= 6; ++i, factor *= 10) {
            int size = sequences[i].size();
            int diffVal = ((currentCount - x * factor) % MOD_A + MOD_A) % MOD_A;
            int pos = lower_bound(sequences[i].begin(), sequences[i].end(), MOD_A - diffVal) - sequences[i].begin();
            totalAnswer = (totalAnswer + 1ll * diffVal * size + partialSum[i]) % MOD_B;
            totalAnswer = (totalAnswer - 1ll * MOD_A * (size - pos) % MOD_B + MOD_B) % MOD_B;
            totalCount += size;
        }
        return;
    }
    ++totalCount;
    totalAnswer = (totalAnswer + ((totalCount - x) % MOD_A + MOD_A) % MOD_A) % MOD_B;
    for (int digit = 0; digit <= 9; ++digit) processNumber(x * 10 + digit);
}

int main() {
    scanf("%lld", &totalN);
    generateSequences(0, 0);
    for (int i = 0; i <= 6; ++i) sort(sequences[i].begin(), sequences[i].end());
    totalCount = 0;
    for (int i = 1; i <= 9; ++i) processNumber(i);
    printf("%lld\n", totalAnswer);
    return 0;
}
